"Doubao-音频生成 1.0(描述定制嗓音:按声纹卡/旁白描述直接生成,免选音色)": "Doubao Audio-Generierung 1.0 (beschreibungsbasierte Stimme: direkt aus der Stimmprofil-Karte / der Erzähler-Beschreibung erzeugt; keine Stimmauswahl)",
"描述定制嗓音:免选音色——角色配音按项目声纹卡(voice.json 声学字段)自动拼装声线描述,旁白按项目旁白声线卡冻结描述(无卡按工单 --instructions);项目已有冻结 voiceprint 样本时自动作参考锚,同一角色逐句/逐段合成不漂音色。": "Beschreibungsbasierte Stimme: keine Stimmenauswahl — Charaktervertonung baut die Stimmbeschreibung automatisch aus der Stimmkarte des Projekts (akustische Felder von voice.json); die Erzählstimme nutzt die eingefrorene Beschreibung der Erzählstimmen-Karte (ohne Karte: --instructions des Auftrags); existiert bereits eine eingefrorene Voiceprint-Probe, dient sie automatisch als Referenzanker, sodass die Stimme bei satz-/segmentweiser Synthese nicht driftet.",
