"未安装 curl,无法测试 SOCKS 代理": "curl ist nicht installiert; SOCKS-Proxys können nicht getestet werden",
"代理地址仅允许本机(127.0.0.1/localhost)": "Proxy-Adresse darf nur lokal sein (127.0.0.1/localhost)",
"说明": "Erläuterung",
"指令": "Erläuterung",
"Agent 高级设置": "Agent-Erweiterte Einstellungen",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度": "Erweiterte Agent-Einstellungen: Parallelität von Fan-out-Agents, Lauf-/Keine-Ausgabe-Timeouts, Budget für rundenübergreifendes Gesprächsgedächtnis, Obergrenze automatischer Wiederholungen, Wartezeit der Wiederholungs-Bestätigung, Denktiefe",
"重跑等待确认(秒)": "Bestätigungswartezeit für Wiederholungen (s)",
"重跑等待确认需为 {min}-{max} 的整数(秒)": "Die Bestätigungswartezeit für Wiederholungen muss eine ganze Zahl zwischen {min} und {max} sein (Sekunden)",
"重跑类确认弹窗(「是否重跑?」等)的等待时长,默认 60 秒:倒计时结束无人答复即自动采用默认选项(通常为「重跑」),流水线不会因等人而卡住。调大可给自己留更多裁决时间,代价是无人值守时流水线在弹窗上等得更久;Agent 显式指定的更短等待仍有效,但不能超过本值。签字类弹窗(H 门人工签字)永不倒计时、永不自动确认,不受本项影响。全局设置,保存后对后续发起的确认生效。": "Wartezeit der Bestätigungs-Popups vom Typ Wiederholung („Erneut ausführen?“ usw.), Standard 60 Sekunden: Läuft der Countdown ohne Antwort ab, wird automatisch die Standardoption (meist „Erneut ausführen“) übernommen, sodass die Pipeline nie hängen bleibt, weil sie auf eine Person wartet. Ein höherer Wert verschafft mehr Entscheidungszeit, dafür wartet die Pipeline unbeaufsichtigt länger am Popup; eine von einem Agent explizit angeforderte kürzere Wartezeit gilt weiterhin, kann diesen Wert aber nie überschreiten. Signatur-Popups (manuelle Signatur der H-Gates) haben nie einen Countdown und bestätigen sich nie selbst, sie sind nicht betroffen. Globale Einstellung; wirkt für nach dem Speichern ausgelöste Bestätigungen.",
"⚙️ Agent 高级设置": "⚙️ Agent-Erweiterte Einstellungen",
"重跑次数": "Wiederholungen",
"Agent 自动重跑/重 roll 的次数上限,默认 0:验收评分、QA 审核或机检不过时,总制片带意见自动退回重做;视频/图像生成机检不达标时自动重 roll。同一任务累计达到该次数仍不过就升级用户裁决,不再自行重试;填 0 则完全不自动重跑,首次不过即升级人工。全局设置,通过运行提示词注入所有 Agent,覆盖流程文档里写死的「最多 3 次」,保存后对后续启动的工单生效。": "Obergrenze, wie oft Agents automatisch erneut ausführen / neu würfeln, Standard 0: Fällt Abnahmebewertung, QA-Prüfung oder Maschinenprüfung durch, schickt der Produzent die Arbeit automatisch mit Anmerkungen zurück; fällt Video-/Bildgenerierung durch die Maschinenprüfung, wird automatisch neu gewürfelt. Erreicht dieselbe Aufgabe diese Zahl und scheitert weiterhin, wird sie zur Entscheidung an den Benutzer eskaliert statt weiter zu wiederholen; 0 deaktiviert automatische Wiederholungen vollständig (der erste Fehlschlag eskaliert sofort). Globale Einstellung, per Laufzeit-Prompt in alle Agents injiziert und übersteuert das in den Workflow-Dokumenten fest verdrahtete „höchstens 3-mal“; gilt für nach dem Speichern gestartete Läufe.",
"重跑次数需为 0-{max} 的整数(0=不自动重跑)": "Die Wiederholungsanzahl muss eine ganze Zahl zwischen 0 und {max} sein (0 = keine automatische Wiederholung)",
"轮次上限": "Runden-Limit",
"单个工单内引擎的对话轮次上限,默认 250:仅对 claude 与 grok 引擎生效(headless 的 --max-turns 参数,不传则不限,这里主动设闸防失控循环);codex/pi/opencode 引擎无此参数不受影响,deepagents 走框架自身的递归上限。撞上限时引擎会被直接切断且无法续跑,回执只显示退出码 1,已落盘的产物保留但核验与回执缺失——大批量工位(逐组选片、批量切片)一单几十组时 100 轮远远不够,如仍撞限优先调小派单批宽、其次上调本值。全局设置,保存后对后续启动的工单生效。": "Obergrenze der Engine-Dialogrunden pro Arbeitsauftrag, Standard 250: wirkt nur auf die Engines claude und grok (Headless-Flag --max-turns; ohne Angabe unbegrenzt — dieses Tor verhindert Endlosschleifen). Die Engines codex/pi/opencode kennen den Parameter nicht und sind nicht betroffen; deepagents nutzt das Rekursionslimit seines Frameworks. Beim Erreichen des Limits wird die Engine hart abgeschnitten und kann nicht fortsetzen — der Beleg zeigt nur Exit-Code 1; bereits gespeicherte Artefakte bleiben erhalten, aber Prüfung und Beleg fehlen. Für Massen-Stationen (Auswahl pro Gruppe, Batch-Schnitt) sind 100 Runden bei Dutzenden Gruppen pro Auftrag viel zu wenig; bei weiterem Anschlagen zuerst die Batch-Breite verkleinern, dann diesen Wert erhöhen. Globale Einstellung; gilt für danach gestartete Aufträge.",
"轮次上限需为 {min}-{max} 的整数": "Das Runden-Limit muss eine ganze Zahl zwischen {min} und {max} sein",
"思考深度": "Denktiefe",
"引擎默认": "Engine-Standard",
"思考深度(Thinking Effort)统一设置,默认「引擎默认」:派单时按当前引擎翻译成各自的推理强度参数——claude → --effort,codex → model_reasoning_effort(无 max,按 xhigh),pi → --thinking,opencode → --variant(模型没有该档位时被忽略),grok → --reasoning-effort(无 max,按 xhigh),deepagents → reasoning_effort(仅云端/OpenRouter 渠道,本地模型不传);kimi CLI 无对应参数,不受影响。越深越稳但越慢、token 消耗越高;「引擎默认」不传任何参数,沿用各引擎自身配置(如 ~/.claude/settings.json 的 effortLevel、~/.codex/config.toml 的 model_reasoning_effort)。全局设置,对所有 Agent 生效,保存后对后续启动的工单生效。": "Einheitliche Einstellung der Denktiefe (Thinking Effort), Standard „Engine-Standard“: beim Dispatch wird sie in den Reasoning-Stärke-Parameter der jeweiligen Engine übersetzt — claude → --effort, codex → model_reasoning_effort (kein max; xhigh wird verwendet), pi → --thinking, opencode → --variant (wird ignoriert, wenn das Modell diese Stufe nicht hat), grok → --reasoning-effort (kein max; auf xhigh abgebildet), deepagents → reasoning_effort (nur Cloud-/OpenRouter-Kanäle; nicht an lokale Modelle gesendet); die kimi-CLI hat keinen entsprechenden Parameter und bleibt unberührt. Tiefer ist stabiler, aber langsamer und token-intensiver; „Engine-Standard“ übergibt nichts und behält die eigene Konfiguration jeder Engine (z. B. effortLevel in ~/.claude/settings.json, model_reasoning_effort in ~/.codex/config.toml). Globale Einstellung für alle Agents, wirksam für nach dem Speichern gestartete Läufe.",
