"最大参考图数量需为 0-30 的整数": "Max. Referenzbilder muss eine ganze Zahl zwischen 0 und 30 sein",
"最大参考视频数量需为 0-10 的整数": "Max. Referenzvideos muss eine ganze Zahl zwischen 0 und 10 sein",
"最大参考音频数量需为 0-10 的整数": "Max. Referenzaudios muss eine ganze Zahl zwischen 0 und 10 sein",
"参考图已满({m} 张),不能再添加": "Referenzbilder voll ({m} Bilder); es können keine weiteren hinzugefügt werden",
"Seedance 2.5(最新,单段30秒直出,参考上限30图+10视频+10音频,480p/720p)": "Seedance 2.5 (neueste Version, 30-Sekunden-Video in einem Durchgang, bis zu 30 Bilder + 10 Videos + 10 Audios als Referenz, 480p/720p)",
"Seedance 2.0(音画同生,多模态生视频,最高4K)": "Seedance 2.0 (Audio und Video gemeinsam, multimodale Videogenerierung, bis 4K)",
"对话记忆": "Gesprächsgedächtnis",
"对话记忆额度(KB,默认 16):创作型 Agent 每次运行接续上次会话,多轮对话有连续记忆;单个会话历史超过该额度自动新开会话防膨胀(扇出型无状态 Agent 本就每单全新会话,不受此项影响)。调大可保留更长的连续记忆,但 resume 每轮重发全部历史,越大越慢、token 消耗越高。拖到 0 即完全关闭:所有 Agent(含总制片)每次运行/发言都是全新会话,跨工单信息只靠落盘产物(bible、工单档案等)传递,可显著省 token,但对话上下文不再延续。全局设置,保存后立即对后续运行生效;调小或关闭期间会话号照常回存,重新调大后从最近一次会话继续。": "Gesprächsgedächtnis-Budget (KB, Standard 16): Kreative Agents setzen bei jedem Lauf ihre vorherige Sitzung fort, sodass mehrstufige Gespräche ein durchgehendes Gedächtnis behalten; überschreitet der Verlauf einer Sitzung dieses Budget, wird automatisch eine neue Sitzung gestartet, um Aufblähung zu verhindern (zustandslose Fan-out-Agents starten ohnehin pro Ticket eine neue Sitzung und sind nicht betroffen). Ein größeres Budget bewahrt längeres durchgehendes Gedächtnis, aber Resume sendet in jeder Runde die gesamte Historie erneut — je größer, desto langsamer und desto höher der Token-Verbrauch. Auf 0 ziehen schaltet das Gedächtnis komplett ab: Jeder Agent — einschließlich des Produzenten — startet bei jedem Lauf/jeder Nachricht eine neue Sitzung; ticketübergreifende Informationen laufen nur über abgelegte Artefakte (Bible, Ticketakten usw.), was deutlich Tokens spart, aber die Gesprächskontinuität aufgibt. Globale Einstellung; wirkt nach dem Speichern sofort für nachfolgende Läufe. Sitzungs-IDs werden auch bei reduziertem oder abgeschaltetem Budget weiter gespeichert — wird es wieder erhöht, geht es mit der letzten Sitzung weiter.",
"✓ 会话恢复生效中:单会话超过 {kb} KB 自动新开": "✓ Sitzungsfortsetzung aktiv: Sitzungen über {kb} KB starten automatisch neu",
"对话记忆需为 0-{max} 的整数(KB,0=关闭)": "Gesprächsgedächtnis muss eine Ganzzahl zwischen 0 und {max} sein (KB, 0 = aus)",
"已关闭:每次运行全新会话": "Aus: jeder Lauf startet eine neue Sitzung",
"跨 Agent 并发额度": "Agentübergreifendes Parallelitätskontingent",
"全局同时运行的工单(工人进程)总上限,默认 8,最高 50:所有 Agent 的运行共用这一池进程槽,占满后新工单排队等槽;总制片等调度型 Agent 大部分时间静默等子任务,不占槽。它同时是下方「单 Agent 并发额度」的取值上限。每个槽 = 一个真实的模型 CLI 进程,调大会同步放大 token 消耗速度、本机负载与网络代理并发压力,建议按机器与额度承受力逐步上调。保存后立即对后续启动的工单生效。": "Globale Obergrenze gleichzeitig laufender Tickets (Worker-Prozesse); Standard 8, maximal 50. Alle Agent-Läufe teilen sich diesen einen Pool von Prozess-Slots; ist er voll, warten neue Tickets auf einen Slot. Dispatcher-Agents wie der Showrunner warten meist still auf Teilaufgaben und belegen keinen Slot. Der Wert ist zugleich die Obergrenze des „Parallelitätskontingents je Agent“ darunter. Jeder Slot = ein echter Modell-CLI-Prozess – ein höherer Wert erhöht Token-Verbrauch, lokale Last und Proxy-Parallelitätsdruck gleichermaßen, daher schrittweise erhöhen, soweit Rechner und Kontingent es tragen. Gilt nach dem Speichern für danach gestartete Läufe.",
"跨 Agent 并发额度需为 1-{max} 的整数": "Das agentübergreifende Parallelitätskontingent muss eine ganze Zahl zwischen 1 und {max} sein",
"单 Agent 并发额度": "Parallelitätskontingent je Agent",
"扇出型 Agent(场景资产、视频生成、审核、验收评分等按场景/组一单的工位)同一 Agent 可同时运行的工单数上限,默认 5,最大不超过上方「跨 Agent 并发额度」。创作型 Agent 为保护会话连续性恒为串行,不受此值影响;全部运行仍受跨 Agent 并发额度总闸。每个并发 = 一个真实的模型 CLI 进程,调大会成倍加快额度消耗,网络代理高并发下也更易断连,建议逐步上调。": "Obergrenze der Tickets, die derselbe Fan-out-Agent (Stationen mit einem Ticket je Szene/Gruppe wie Szenen-Assets, Videogenerierung, Prüfung, Abnahmebewertung) gleichzeitig ausführen darf; Standard 5, höchstens das obige „agentübergreifende Parallelitätskontingent“. Kreative Agents laufen zum Schutz der Sitzungskontinuität stets seriell und sind nicht betroffen; alle Läufe unterliegen weiterhin dem agentübergreifenden Tor. Jede Parallelität = ein echter Modell-CLI-Prozess – ein höherer Wert beschleunigt den Kontingentverbrauch entsprechend und erhöht bei hoher Parallelität Proxy-Abbrüche, daher schrittweise erhöhen.",
"运行超时(分钟)": "Lauf-Timeout (Min.)",
"无输出超时(分钟)": "Timeout ohne Ausgabe (Min.)",
"运行超时:单个工单从启动算起的墙钟上限,默认 120 分钟(总制片要等整条流水线,自动放宽 4 倍),到点连同派生子进程一起终止并记为出错,是回收挂死进程的最后防线。无输出超时:引擎连续多长时间没有任何事件输出即判定挂死并终止,默认 30 分钟,填 0 关闭;比墙钟更早识别 API 长连接不返回、代理断流等假死,又不会误伤跑得慢但在正常干活的长批量任务(总制片大部分时间静默等子任务,不受此项约束)。注意单次工具调用期间引擎不会有事件输出,该值须大于工单里最长的一次工具调用。均为全局设置,保存后对后续启动的工单生效。": "Lauf-Timeout: Wanduhr-Obergrenze eines Tickets ab Start, Standard 120 Minuten (der Produzent wartet auf die gesamte Pipeline und erhält automatisch das 4-Fache); bei Ablauf werden der Lauf samt Kindprozessen beendet und als Fehler markiert – die letzte Verteidigungslinie gegen hängende Prozesse. Timeout ohne Ausgabe: wie lange die Engine ohne jedes Ereignis bleiben darf, bevor sie als hängend gilt und beendet wird, Standard 30 Minuten, 0 deaktiviert; erkennt Hänger (nie zurückkehrende API-Langverbindungen, Proxy-Abbrüche) viel früher als die Wanduhr, ohne langsame, aber gesunde Batch-Jobs zu treffen (der Produzent wartet meist still auf Teilaufgaben und ist ausgenommen). Achtung: Während eines einzelnen Tool-Aufrufs sendet die Engine keine Ereignisse, der Wert muss also den längsten Tool-Aufruf des Tickets übersteigen. Beides globale Einstellungen; gelten für nach dem Speichern gestartete Läufe.",
"运行超时需为 {min}-{max} 的整数(分钟)": "Lauf-Timeout muss eine Ganzzahl zwischen {min} und {max} sein (Minuten)",
"无输出超时需为 0-{max} 的整数(分钟,0=关闭)": "Timeout ohne Ausgabe muss eine Ganzzahl zwischen 0 und {max} sein (Minuten, 0 = aus)",
"并发额度需为 1-{max} 的整数": "Das Parallelitätskontingent muss eine ganze Zahl zwischen 1 und {max} sein",
