"工作流在": "Workflows laufen in der offiziellen Cloud von",
"官方云端执行,无需本地部署;API Key 在": "— keine lokale Installation nötig; API-Key auf",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(须为 API 格式);依赖自定义节点的工作流(如 ACE-Step/IndexTTS-2/MiniMax-H3)在云端可能不可用,以「测试连接」结果为准": "erstellen (Comfy-Cloud-Abo erforderlich, monatliche Credits werden mit der Web-Version geteilt; der Gratis-Tarif hat keinen API-Zugang); das Workflow-Dropdown ist identisch mit lokal (API-Format erforderlich); Workflows mit Custom-Nodes (ACE-Step/IndexTTS-2/MiniMax-H3) sind in der Cloud ggf. nicht verfügbar — maßgeblich ist das Ergebnis von „Verbindung testen“",
"本地模型": "Lokales Modell",
"云端模型": "Cloud-Modell",
"所有 OpenAI 兼容 API 均可使用(默认 DeepSeek 官方端点):换 Base URL / API Key / 模型 ID 即可接入其他服务商;「测试连接」会列出端点上可用的模型": "Jede OpenAI-kompatible API ist nutzbar (Standard: offizieller DeepSeek-Endpunkt): Base URL / API-Key / Modell-ID ändern, um einen anderen Anbieter anzubinden; „Verbindung testen“ listet die auf dem Endpunkt verfügbaren Modelle",
"sk-…(DeepSeek 开放平台创建;其他 OpenAI 兼容服务商 Key 亦可)": "sk-… (auf der offenen DeepSeek-Plattform erstellt; Keys anderer OpenAI-kompatibler Anbieter gehen auch)",
