"材质": "Material",
"构想与风格保存在项目的 brief.md,注入该项目每个 Agent 的系统提示词,作为最高创作前提;画面风格约束全部画面视觉产出。保存后对之后派发的任务生效;全部清空保存则移除该设定。叙事节奏改在「视频节奏」设置中配置": "Konzept und Stil werden in brief.md des Projekts gespeichert und jedem Agenten als oberste kreative Vorgabe in den System-Prompt injiziert; der Bildstil bindet alle visuellen Ausgaben. Gilt für nach dem Speichern verteilte Aufgaben; leer speichern entfernt die Einstellung. Der Erzählrhythmus wird jetzt unter „Videorhythmus“ konfiguriert",
"叙事节奏保存在项目的 brief.md 并注入每个 Agent 的系统提示词,节拍链约束剧本分集/分场与分镜节拍": "Der Erzählrhythmus wird in brief.md des Projekts gespeichert und jedem Agenten in den System-Prompt injiziert; seine Beat-Kette bindet die Episoden-/Szenenaufteilung und das Storyboard-Tempo",
