",自动运行每次唤醒总制片时都随消息附带,总制片会话重开也不丢失;适合放长期约束,建议写成条件式(如「在 ep01-ep10 剧本全部完成前,不派设定类工单」),留空则不附带": ", wird jeder Weck-Nachricht des Automatikbetriebs beigefügt und geht auch nach einem Sitzungsneustart nicht verloren; geeignet für langfristige Vorgaben, am besten als Bedingung formuliert (z. B. 「bis alle Drehbücher von ep01-ep10 fertig sind, keine Design-Arbeitsaufträge vergeben」); leer lassen, um nichts anzuhängen",
