"闲置时间:每隔该时长巡检一次,流水线空闲(无任务在跑、无待确认项)才发送状态检查消息,默认 5 分钟。阈值:总制片生效引擎(claude/codex)的 5 小时窗口会话用量达到该值时,本轮不发送;用量读取不到时放行。均为全局设置,对所有项目生效(开关在运行面板 🤖 按钮,按项目独立)": "Leerlaufzeit: In diesem Intervall wird geprüft; nur bei leerlaufender Pipeline (keine laufenden Aufgaben, nichts zu bestätigen) wird eine Statusprüfungs-Nachricht gesendet, Standard 5 Minuten. Schwelle: Erreicht die Nutzung im 5-Stunden-Fenster der aktiven Engine des Producers (claude/codex) diesen Wert, wird in dieser Runde nicht gesendet; ist die Nutzung nicht auslesbar, wird gesendet. Beides globale Einstellungen für alle Projekte (Schalter über die 🤖 Taste im Run-Panel, pro Projekt separat)",
