"推送图片/视频还需在应用权限里开通 im:resource;之后新完成的人物/场景/道具主图与分镜组视频会自动推送到飞书。": "Für den Push von Bildern/Videos muss zusätzlich die Berechtigung im:resource für die App aktiviert werden; danach werden neu fertiggestellte Haupt-Bilder von Figuren/Szenen/Requisiten sowie Storyboard-Gruppen-Videos automatisch an Feishu gesendet.",
"文件大小上限": "Dateigrößenlimit",
"MB;超过此大小的图片/视频不推送,只发一条文字提示。默认 5MB;平台上限图片 10MB、视频 30MB": "MB; größere Bilder/Videos werden nicht gesendet, nur ein Texthinweis. Standard 5 MB; Plattformlimit: Bilder 10 MB, Videos 30 MB",
"尚未绑定 WhatsApp。点击下方按钮生成二维码,用手机 WhatsApp 把本系统添加为「已连接的设备」。": "Noch kein WhatsApp verknüpft. Klicken Sie unten, um einen QR-Code zu erzeugen, und fügen Sie dieses System im WhatsApp Ihres Handys als „verknüpftes Gerät“ hinzu.",
"打开手机 WhatsApp → 设置 → 已连接的设备 → 连接设备,扫描上方二维码": "Öffnen Sie WhatsApp am Handy → Einstellungen → Verknüpfte Geräte → Gerät verknüpfen und scannen Sie den QR-Code oben",
"正在生成二维码…": "QR-Code wird erzeugt…",
"以你自己账号的「已连接的设备」方式接入(同 WhatsApp 网页版),只把「给自己发消息」(Message Yourself)的自聊当作指令通道;他人发来的消息不会被读取或转发。": "Verbindet sich als „verknüpftes Gerät“ Ihres eigenen Kontos (wie WhatsApp Web); nur der Selbst-Chat („Message Yourself“) dient als Befehlskanal – Nachrichten anderer Personen werden weder gelesen noch weitergeleitet.",
"WhatsApp 已绑定": "WhatsApp verknüpft",
"正在连接 WhatsApp 服务…": "Verbindung zu WhatsApp wird hergestellt…",
"确定解除 WhatsApp 绑定?将登出「已连接的设备」并删除本地会话。": "WhatsApp-Verknüpfung aufheben? Das „verknüpfte Gerät“ wird abgemeldet und die lokale Sitzung gelöscht.",
"绑定后,你在手机端发的消息会作为给总制片的指令进入当前项目的对话,与在控制台输入完全等效。": "Nach der Verknüpfung gelangen Ihre vom Handy gesendeten Nachrichten als Anweisungen an den Producer in die Konversation des aktuellen Projekts – genau wie eine Eingabe in der Konsole.",
"总制片的回复会同步推送到所有已绑定的通道;系统自动消息(设置变更通知、自动运行巡检等)也会一并推送。": "Antworten des Producers werden an alle verknüpften Kanäle übertragen; automatische Systemmeldungen (Hinweise zu Einstellungsänderungen, Auto-Run-Kontrollen usw.) ebenfalls.",
