"(两平台账号与 Key 不互通,「接口区域」须与 Key 来源一致);克隆音色需先在平台创建;Agent 可用 --voice 按角色覆盖(传 voice_id)": " (Konten und Keys sind zwischen den beiden Plattformen nicht austauschbar; die “API-Region” muss zur Herkunft des Keys passen); geklonte Stimmen müssen zuerst auf der Plattform erstellt werden; Agents können pro Figur mit --voice überschreiben (voice_id übergeben)",
