"Voice Design:按角色嗓音的文字描述生成嗓音样本(人物嗓音设计时用);Voice Clone:按嗓音样本 + 对白文字生成对白。两者按用途自动选择;未配置 Voice Design 时一律走 Voice Clone": "Voice Design: erzeugt aus einer Textbeschreibung der Figurenstimme ein Stimm-Sample (beim Entwerfen einer Figurenstimme). Voice Clone: erzeugt Dialog aus einem Stimm-Sample plus Dialogtext. Beide werden je nach Zweck automatisch gewählt; ohne konfiguriertes Voice Design läuft alles über Voice Clone",
