"待提交问题:Agent 运行中发现系统代码缺陷或需要新增功能时自动整理成 issue,点击查看并提交给开发者,让你的客户端运行得更好": "Einzureichende Probleme: Findet ein Agent während eines Laufs einen Defekt im App-Code oder eine fehlende Funktion, wird automatisch ein Issue aufbereitet; klicken, prüfen und an die Entwickler einreichen, damit Ihr Client besser läuft",
"Agent 运行中确认问题属于系统代码缺陷、或需要系统新增功能时,自动整理成 issue 列在下方,点「提交」即打开预填好的 GitHub 页面由你确认提交。": "Wenn ein Agent während eines Laufs bestätigt, dass ein Problem ein Defekt im App-Code ist oder die App eine neue Funktion benötigt, wird es automatisch als Issue aufbereitet und unten aufgelistet; „Einreichen“ öffnet eine vorausgefüllte GitHub-Seite zur Bestätigung.",
"问题只写机制,内容已脱敏(路径、项目名、密钥),不含剧情、提示词与项目内容。": "Issues beschreiben nur Mechanismen; der Inhalt wurde bereinigt (Pfade, Projektnamen, Schlüssel) und enthält keine Handlung, Prompts oder Projektinhalte.",
"✓ 已提交": "✓ Eingereicht",
