"火山方舟私域虚拟人像素材库:人物形象图入库后,生成视频时自动以资产 URI 提交,规避人脸参考图审核拦截": "Private virtuelle Porträt-Bibliothek von Volcano Ark: Nach der Registrierung eines Charakterbilds wird es bei der Videogenerierung automatisch als Asset-URI übermittelt und umgeht so Moderationsblockaden für Gesichtsreferenzen",
"🧑‍🎨 虚拟人像资产库": "🧑‍🎨 Virtuelle Porträt-Bibliothek",
"火山方舟私域素材库:入库的人物形象图在生成视频时以资产 URI 提交,规避人脸参考图审核拦截": "Private Volcano-Ark-Bibliothek: Registrierte Charakterbilder werden bei der Videogenerierung als Asset-URI übermittelt und umgehen Moderationsblockaden für Gesichtsreferenzen",
"📋 使用前准备": "📋 Vorbereitung",
"在火山方舟开通": "Aktivieren Sie in Volcano Ark das",
