"(私域虚拟人像素材库的前置条件)。": "(Voraussetzung für die private Porträt-Bibliothek).",
"在火山引擎控制台": "Öffnen Sie in der Volcano-Engine-Konsole",
"API 访问密钥管理": "API-Zugriffsschlüssel-Verwaltung",
"创建并获取 Access Key / Secret Key(IAM 密钥,非 ark- 开头的方舟 API Key),填入下方并保存。": "erstellen und beziehen Sie Access Key / Secret Key (IAM-Schlüssel, kein Ark-API-Key mit ark--Präfix), tragen Sie sie unten ein und speichern Sie.",
"点击「启用」后,可在下方管理已入库的素材;人物预览页每张形象图会出现「入库」按钮,分镜重出时已入库(Active)的参考图自动以资产 URI(asset://素材ID)提交。": "Nach Klick auf „Aktivieren“ verwalten Sie unten die registrierten Assets; jedes Bild in der Charaktervorschau erhält einen „Registrieren“-Button, und bei der Neugenerierung einer Gruppe werden registrierte (Active) Referenzbilder automatisch als Asset-URI (asset://Asset-ID) übermittelt.",
"注意:上传入库为异步审核(Processing → Active/Failed),仅 Active 状态的素材可用于视频生成;素材按方舟「项目」隔离,下方 ProjectName 须与「生成模型」页视频生成所用方舟 API Key 所属项目一致(默认 default)。": "Hinweis: Die Registrierung wird asynchron geprüft (Processing → Active/Failed); nur Active-Assets sind für die Videogenerierung nutzbar. Assets sind je Ark-Projekt isoliert — der ProjectName unten muss zum Projekt des Ark-API-Keys auf der Seite Generierungsmodelle passen (Standard: default).",
"🔑 密钥与开关": "🔑 Schlüssel & Schalter",
"Access Key / Secret Key 留空时,自动使用「⚙️ 设置 → 文件托管 → 火山引擎 TOS」已配置的 AK/SK(或环境变量 TOS_ACCESS_KEY/TOS_SECRET_KEY)。": "Bleiben Access Key / Secret Key leer, werden automatisch die unter ⚙️ Einstellungen → Datei-Hosting → Volcano TOS konfigurierten AK/SK (oder die Umgebungsvariablen TOS_ACCESS_KEY/TOS_SECRET_KEY) verwendet.",
"default(须与视频生成 API Key 所属项目一致)": "default (muss zum Projekt des Videogenerierungs-API-Keys passen)",
"文件托管自检:": "Datei-Hosting-Selbsttest: ",
