"Qwen Image 3(Fal 托管;中英提示词,参考图 ≤3,支持负面提示词)": "Qwen Image 3 (auf Fal gehostet; chinesische/englische Prompts, bis zu 3 Referenzbilder, Negativ-Prompt möglich)",
"HunyuanImage 3.0(Fal 托管;仅文生图,支持负面提示词)": "HunyuanImage 3.0 (auf Fal gehostet; nur Text-zu-Bild, Negativ-Prompt möglich)",
"Fal 图像生成 API(queue.fal.run 异步队列,托管 Seedream、Nano Banana、GPT Image、FLUX.2、Qwen Image 等端点);模型 ID 填家族前缀,无参考图走文生图端点、有参考图自动切 edit 端点,「自定义…」也可填完整端点 ID;尺寸/参考图上限/seed 按模型映射;Key 与视频段 Fal 共用(任一处填写即可),在": "Fal-Bildgenerierungs-API (asynchrone Warteschlange queue.fal.run mit Endpunkten für Seedream, Nano Banana, GPT Image, FLUX.2, Qwen Image u. a.); die Modell-ID ist das Familienpräfix – ohne Referenzen wird der Text-zu-Bild-Endpunkt genutzt, mit Referenzen automatisch der Edit-Endpunkt; unter „Benutzerdefiniert…“ geht auch eine vollständige Endpunkt-ID; Größe / Referenzlimits / Seed werden je Modell abgebildet; der Key wird mit dem Tab Video → Fal geteilt (eine Stelle genügt) und wird erstellt unter",
"MiniMax H3 Max(Fal 托管;H3 后训练版,提示遵循更强)": "MiniMax H3 Max (auf Fal gehostet; nachtrainiertes H3, stärkere Prompt-Treue)",
"MiniMax H3 Max Turbo(Fal 托管;速度优先版,仅文生/首尾帧,480P/768P,不支持参考素材)": "MiniMax H3 Max Turbo (auf Fal gehostet; geschwindigkeitsoptimierte Variante, nur Text/Start-Endframe, 480P/768P, keine Referenzmaterialien)",
"Kling 3.0 Pro(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Pro (auf Fal gehostet; Start-/Endframe, 3–15 s, natives Audio, keine Referenzmaterialien)",
"Kling 3.0 Standard(Fal 托管;首尾帧,3-15 秒,原生音频,不支持参考素材)": "Kling 3.0 Standard (auf Fal gehostet; Start-/Endframe, 3–15 s, natives Audio, keine Referenzmaterialien)",
"Fal 视频生成 API(queue.fal.run 异步队列,托管 Seedance 2.0/2.5、MiniMax H3、Kling 3.0、Wan 3.0 等端点);模型 ID 填家族前缀,按输入自动补 text-to-video / image-to-video / reference-to-video 任务段,「自定义…」也可填完整端点 ID;分辨率/时长/参考素材上限随所选模型(与官方渠道同口径);Key 在": "Fal-Videogenerierungs-API (asynchrone Warteschlange queue.fal.run mit Endpunkten für Seedance 2.0/2.5, MiniMax H3, Kling 3.0, Wan 3.0 u. a.); die Modell-ID ist das Familienpräfix, das Aufgabensegment text-to-video / image-to-video / reference-to-video wird je nach Eingaben automatisch angehängt, oder über „Benutzerdefiniert…“ eine vollständige Endpunkt-ID eintragen; Auflösungs-/Dauer-/Referenzlimits folgen dem gewählten Modell (gleiche Regeln wie die offiziellen Kanäle); Key im",
"fal.ai 控制台「API Keys」": "fal.ai-Dashboard „API Keys“",
"直播": "Live",
"直播:参考图 + 提示词交给 Fal 渠道视频模型循环生成 480p 短段,每段带上一段尾帧续接,页面把新段接在已播内容之后连续播放": "Live: Referenzbilder + Prompt gehen an ein Fal-Videomodell, das fortlaufend 480p-Clips erzeugt, jeder setzt am letzten Frame des vorherigen an; die Seite hängt neue Clips hinter das bereits Abgespielte für eine durchgehende Wiedergabe",
"直播 — Agentics:VideoAgents": "Live — Agentics:VideoAgents",
"📡 直播": "📡 Live",
"参考图 + 提示词 → Fal 视频模型循环生成 480p 短段 → 尾帧续接 → 连续播放": "Referenzen + Prompt → Fal-Videomodell erzeugt 480p-Clips in Schleife → Fortsetzung ab letztem Frame → durchgehende Wiedergabe",
"🗑 清理历史片段": "🗑 Alte Clips löschen",
