"人物/场景/风格锚图;每一轮都会连同上一段的尾帧一起作为参考提交,保持人物一致。启动后冻结,停止后可改。": "Ankerbilder für Figuren/Szene/Stil; in jeder Runde werden sie zusammen mit dem letzten Frame des vorherigen Clips als Referenz gesendet, damit die Figuren konsistent bleiben. Nach dem Start eingefroren, nach dem Stopp änderbar.",
