"例如:一位年轻主播坐在暖光直播间里,面对镜头微笑聊天,偶尔喝一口咖啡,背景霓虹灯牌缓慢闪烁": "z. B. Ein junger Streamer sitzt in einem warm beleuchteten Studio, lächelt und plaudert in die Kamera, nippt ab und zu am Kaffee, im Hintergrund flackert langsam ein Neonschild",
