"MiniMax H3 Max Director(导演模式专用,实时 WebRTC)": "MiniMax H3 Max Director (nur Regie-Modus, Echtzeit-WebRTC)",
"导演模式按秒计费(最少 60 秒),单会话默认最长 2 分钟(更长需向 fal 申请);关闭页面即结束": "Regie-Modus wird sekundengenau abgerechnet (mind. 60 s); eine Sitzung ist standardmäßig auf 2 Min. begrenzt (länger nur mit fal-Freigabe); Schließen der Seite beendet sie",
