"播放策略:按顺序播放已生成的片段;新片段还没到时重播最新一段,到了就在当前段结束后接上,不会打断正在播的画面。生成通常慢于播放,所以\"回放\"是常态——把单段时长调长可以减少重播占比。待播片段达到上限(默认 3 段,高级选项可调)时暂停生成,播掉一段再继续。停止后循环回放全部片段。": "Wiedergabe: erzeugte Clips laufen der Reihe nach; solange der nächste fehlt, wird der neueste wiederholt, und ein neuer Clip wird nach dem laufenden angehängt, ohne ihn zu unterbrechen. Die Erzeugung ist meist langsamer als die Wiedergabe, Wiederholungen sind also normal – längere Clips verringern den Anteil. Beim Erreichen des Wartelimits (Standard 3, in den erweiterten Optionen einstellbar) pausiert die Erzeugung und läuft weiter, sobald einer abgespielt ist. Nach dem Stopp laufen alle Clips in Schleife.",
