"语音输入": "Spracheingabe",
"语音输入:开启后控制台与预览页「修改」浮窗的输入框出现麦克风按钮,录音由本机 faster-whisper 转成文字,音频不出本机": "Spracheingabe: Wenn aktiviert, erscheint ein Mikrofon-Button im Konsolen-Eingabefeld und im „Überarbeiten“-Fenster der Vorschauseiten; Aufnahmen werden lokal mit faster-whisper transkribiert und verlassen den Rechner nicht",
"🎤 语音输入": "🎤 Spracheingabe",
"启用语音输入": "Spracheingabe aktivieren",
"开启后控制台输入框与预览页「修改」浮窗的右侧出现麦克风按钮:点一下开始录音、再点一下结束,录音由本机 faster-whisper 模型转成文字插到光标处(最长 60 秒,音频不出本机,不需要任何 API Key)。识别语言跟随界面语言。模型首次使用需先下载,越大的模型越准但越慢:small 起步够用,Apple 芯片可选 medium 或 large-v3-turbo。": "Wenn aktiviert, erscheint rechts im Konsolen-Eingabefeld und im „Überarbeiten“-Fenster der Vorschauseiten ein Mikrofon-Button: einmal klicken startet die Aufnahme, erneut klicken beendet sie; die Aufnahme wird vom lokalen faster-whisper-Modell transkribiert und an der Cursorposition eingefügt (max. 60 s, Audio verlässt den Rechner nicht, kein API-Key nötig). Die Erkennungssprache folgt der UI-Sprache. Das Modell muss vor der ersten Nutzung geladen werden; größere Modelle sind genauer, aber langsamer: small reicht zum Start, auf Apple Silicon auch medium oder large-v3-turbo.",
