"机检未跑": "Prüfung nicht gelaufen",
"出成片 = 各组当前版本归一化拼正片(cut_post)→ 转场重渲(render_transitions)→ 终版封装(finalize_episode assemble,含片头平移与 intro_offset_ok 机检)→ 后期机检。全部宿主 CLI,几分钟量级。": "Endfassung rendern = aktuelle Versionen aller Gruppen normalisieren und zusammensetzen (cut_post) → Übergänge neu rendern (render_transitions) → Endpaketierung (finalize_episode assemble, inkl. Intro-Verschiebung und Prüfung intro_offset_ok) → Post-Prüfung. Alles Host-CLI, wenige Minuten.",
