"把时间段按倍率放慢(1s ×2 = 2s):RIFE 类工作流补帧后由宿主变速拼接,成片按拉长量变长,外挂声轨与字幕按 timemap 自动平移;声音 stretch = 保音高拉伸(段内有台词时改 sustain / fade / mute)": "Den markierten Zeitabschnitt um den Faktor verlangsamen (1 s ×2 = 2 s): ein RIFE-Workflow berechnet Zwischenbilder, dann retimt und fügt der Host zusammen. Die Folge wird um die Dehnung länger; externe Tonspur und Untertitel verschieben sich über dieselbe Zeitkarte. Ton stretch = tonhöhenerhaltende Dehnung (bei Dialog im Abschnitt auf sustain / fade / mute wechseln)",
