"人声保留 dB": "Stimme behalten (dB)",
"环境声保留 dB": "Umgebungston behalten (dB)",
"用本机人声分离模型把对白 / 人声从原生声轨里去掉,保留音效、环境声和配乐;画面不重编码。人声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "Entfernt mit einem lokalen Stimmtrennungsmodell Dialog / Stimmen aus der Originaltonspur; Soundeffekte, Atmo und Musik bleiben erhalten; das Bild wird nicht neu kodiert. Stimme behalten -60 = vollständig entfernt, höher = nur abgesenkt. Das Modell (ca. 64 MB) wird bei der ersten Verwendung heruntergeladen; nach dem Einreichen muss die Mischung neu laufen, damit die Änderung in die Endfassung kommt",
"只留人声:用本机人声分离模型把音效、环境声和配乐从原生声轨里去掉;画面不重编码。环境声保留 -60 = 完全去掉,调高 = 只压低。首次使用自动下载模型(约 64 MB);提交后要重跑混音才进成片": "Nur Stimmen behalten: entfernt mit einem lokalen Stimmtrennungsmodell Soundeffekte, Atmo und Musik aus der Originaltonspur; das Bild wird nicht neu kodiert. Umgebungston behalten -60 = vollständig entfernt, höher = nur abgesenkt. Das Modell (ca. 64 MB) wird bei der ersten Verwendung heruntergeladen; nach dem Einreichen muss die Mischung neu laufen, damit die Änderung in die Endfassung kommt",
