// 分镜剪辑·插黑 / 定格(2026-09-17)
"插黑 / 定格": "Schwarz / Standbild",
"把选中的时间段直接删掉,剩下的内容按原顺序拼成本组新版本(时长变短,出成片时外挂声轨/字幕按时间映射表自动同步)": "Die markierten Bereiche werden entfernt und der Rest in Originalreihenfolge zu einer neuen Version dieser Gruppe verbunden (Laufzeit wird kürzer; beim Finalisieren werden externe Tonspur und Untertitel über die Zeitkarte neu synchronisiert)",
"控制切换节奏:在当前时刻插入「前一帧定格 + 黑场」生成本组新版本;或放在本组开头 / 结尾的组边界,写成组间转场调整(提交即回写 shot_list,出成片时插帧)。成片按插入量变长,外挂声轨与字幕按同一张时间映射表自动平移;黑场声音可延续前段、淡出或静音": "Rhythmus steuern: an der Abspielposition „Standbild des vorigen Frames + Schwarz“ einfügen und eine neue Version bauen, oder an der Grenze am Anfang / Ende dieser Gruppe als Gruppenübergangs-Anpassung eintragen (Einreichen schreibt sie in shot_list; Frames werden beim Finalisieren eingefügt). Die Folge wird um die Einfügung länger; externe Tonspur und Untertitel verschieben sich über dieselbe Zeitkarte; der Ton unter Schwarz kann halten, ausblenden oder stumm sein",
"分镜剪辑,四个模块:① 删段——选中的时间段直接删除,剩余拼成新版本;② 换段——切掉的时间段用本组另一版本同段替代;③ 插黑 / 定格——在当前时刻或组边界插入定格帧 + 黑场控制切换节奏;④ 派单剪辑师——输入指令发给剪辑师工位,产物登记为新版本": "Schnitt, vier Module: ① Löschen — markierte Bereiche entfernen, Rest wird neue Version; ② Ersetzen — geschnittene Bereiche durch dieselben Bereiche einer anderen Version ersetzen; ③ Schwarz / Standbild — Standbild + Schwarz an der Abspielposition oder Gruppengrenze einfügen, um den Rhythmus zu steuern; ④ An Editor senden — Anweisung an den Editor-Agenten, Ergebnis wird neue Version",
"+{s}s → {r}s": "+{s}s → {r}s",
"{a} → {b} 的组边界:前组尾定格 / 黑场后进入本组(写入本组的组间转场调整)": "Grenze {a} → {b}: letzten Frame der vorigen Gruppe halten / Schwarz, dann diese Gruppe (als Übergangsanpassung dieser Gruppe)",
"{a} → {b} 的组边界:本组尾定格 / 黑场后进入下组(写入下组的组间转场调整)": "Grenze {a} → {b}: letzten Frame dieser Gruppe halten / Schwarz, dann nächste Gruppe (als Übergangsanpassung der nächsten Gruppe)",
