"高斯模糊与原片按强度混合,压掉高频细节而不糊轮廓(回忆/梦境段的柔焦感);半径随画面高度等比缩放": "Mischt einen Gaußschen Weichzeichner je nach Stärke mit dem Original und nimmt feine Details heraus, ohne Konturen zu verschmieren (Weichzeichner-Look für Rückblenden / Träume); der Radius skaliert mit der Bildhöhe",
"全部集": "Alle Episoden",
"按集过滤:只显示该集出现的资产": "Nach Episode filtern: nur Assets anzeigen, die darin vorkommen",
"Agent 高级设置:扇出型 Agent 并发额度、运行/无输出超时、跨轮对话记忆额度、自动重跑次数上限、重跑等待确认时间、思考深度、白模自检、Debug 模式": "Erweiterte Agent-Einstellungen: Parallelität von Fan-out-Agents, Lauf-/Keine-Ausgabe-Timeouts, Budget für rundenübergreifendes Gesprächsgedächtnis, Obergrenze automatischer Wiederholungen, Wartezeit der Wiederholungs-Bestätigung, Denktiefe, Whitebox-Selbstprüfung, Debug-Modus",
"白模自检": "Whitebox-Selbstprüfung",
"显示 SOUL.md 等开发者入口": "Entwickler-Einstiege wie SOUL.md anzeigen",
"白模调度编译后出静帧自检取景": "Nach dem Kompilieren des Whitebox Standbilder rendern, um die Kadrierung selbst zu prüfen",
"默认勾选:白模调度 Agent 每次新建或修改分镜白模、编译通过后,用宿主命令 render_whitebox.py --stills 对本单改动过的组做无头渲染——每镜取首/中/尾等时刻的摄影机视角加一张空间视角,拼成每组一张联系表(项目 directing 下该集的 whitebox/stills 目录),Agent 读图核对主体是否在画内、有无被墙或道具遮挡、正面/背影与调度是否一致、景别是否相符,有问题先自行修正或开待决项,再交你在预览页审看签字。渲染全在本机完成,不调用任何生成模型、不产生费用,也不导出 camera.mp4(导出仍须 H3W 签字);每组约多花十几秒与一次读图的 token。取消勾选则只做数值自检与宿主机检,不出静帧。全局设置,通过运行提示词注入白模调度 Agent,保存后对后续启动的工单生效。": "Standardmäßig aktiviert: Jedes Mal, wenn der Whitebox-Staging-Agent ein Storyboard-Whitebox neu erstellt oder ändert und die Kompilierung durchläuft, führt er den Host-Befehl render_whitebox.py --stills für die in diesem Auftrag geänderten Gruppen aus. Gerendert wird headless: pro Einstellung Kameraansichten am Anfang / in der Mitte / am Ende (und zu weiteren Schlüsselmomenten) plus eine Raumansicht, zusammengefügt zu einem Kontaktbogen pro Gruppe (im Ordner whitebox/stills der Episode unter directing des Projekts). Der Agent liest den Bogen und prüft, ob das Motiv im Bild ist, nichts von Wänden oder Requisiten verdeckt wird, Vorder- / Rückansicht zur Inszenierung passen und die Einstellungsgröße stimmt; Probleme behebt er selbst oder eröffnet einen offenen Punkt, bevor er Ihnen zur Prüfung und Freigabe in der Vorschauseite übergibt. Das Rendern erfolgt vollständig lokal: kein Generierungsmodell wird aufgerufen, es entstehen keine Kosten, und camera.mp4 wird nicht exportiert (der Export erfordert weiterhin die H3W-Freigabe); pro Gruppe fallen etwa zehn zusätzliche Sekunden und die Tokens eines Bildlesevorgangs an. Deaktiviert: nur numerische Selbstprüfungen und Host-Prüfungen, keine Standbilder. Globale Einstellung, wird über den Lauf-Prompt in den Whitebox-Staging-Agent injiziert; gilt für Aufträge, die nach dem Speichern gestartet werden.",
"本组尚未白模调度，当前没有可审看的白模。": "Diese Gruppe wurde noch nicht per Whitebox-Staging bearbeitet; es gibt noch keine Whitebox zur Abnahme.",
"白模调度 Agent 完成本集工单后这里会显示正式白模；在此之前无需对白模提修改意见。": "Die offizielle Whitebox erscheint hier, sobald der Whitebox-Staging-Agent den Auftrag dieser Folge abgeschlossen hat; bis dahin sind keine Änderungswünsche zur Whitebox nötig.",
"系统按分镜与动线自动推断的粗略白模，机位、走位、朝向多为估计值，不是白模调度的交付物": "Grobe Whitebox, vom System automatisch aus Storyboard und Blocking abgeleitet; Kamerapositionen, Laufwege und Blickrichtungen sind überwiegend Schätzwerte und kein Ergebnis des Whitebox-Stagings",
"查看自动推断草稿（仅供参考，不接受修改）": "Automatisch abgeleiteten Entwurf ansehen (nur zur Orientierung, keine Änderungen möglich)",
"自动推断草稿": "Automatisch abgeleiteter Entwurf",
"自动推断草稿：本组未经白模调度，以下画面由系统按分镜与动线粗略推断，仅供参考；修改入口在白模调度完成后开放。": "Automatisch abgeleiteter Entwurf: Diese Gruppe wurde noch nicht per Whitebox-Staging bearbeitet. Das Bild unten ist grob aus Storyboard und Blocking abgeleitet und dient nur zur Orientierung; Änderungen sind nach Abschluss des Whitebox-Stagings möglich.",
"本组尚未白模调度,当前是系统自动推断的草稿,只能查看;白模调度完成后再提修改": "Diese Gruppe wurde noch nicht per Whitebox-Staging bearbeitet; zu sehen ist ein automatisch abgeleiteter Entwurf, nur zur Ansicht. Änderungen bitte nach Abschluss des Whitebox-Stagings",
