"勾选:在手绘稿基础上由 AI 按对应风格重绘;不勾选:直接使用手绘原图": "Aktiviert: Die KI zeichnet deine Skizze im passenden Stil neu; deaktiviert: Die Originalzeichnung wird unverändert verwendet",
"画一张分镜草图,提交后 AI 按分镜草图风格重绘,作为该镜草图": "Zeichne eine Storyboard-Skizze; nach dem Absenden zeichnet die KI sie im Storyboard-Skizzenstil neu und sie wird zur Skizze dieser Einstellung",
"可选:补充说明(构图/人物/动作,AI 重绘时参考)": "Optional: ergänzende Hinweise (Bildaufbau / Figuren / Aktion) für die KI-Neuzeichnung",
"手绘原图将直接加入本组参考图(不经 AI 加工)": "Die Originalzeichnung wird direkt zu den Referenzbildern dieser Gruppe hinzugefügt (ohne KI-Bearbeitung)",
