"✅ 已提交 {f},手绘原图已直接加入本组参考图,请回桌面端查看": "✅ {f} gesendet; die Originalzeichnung wurde zu den Referenzbildern dieser Gruppe hinzugefügt – auf dem Desktop ansehen",
"手机扫码手绘构图线稿;勾选「AI 加工」(默认)结合已有参考图按项目风格生成最终参考图,不勾选则手绘原图直接加入本组": "Mit dem Handy scannen und eine Layoutskizze zeichnen; mit „KI-Überarbeitung“ (Standard) wird daraus mit den vorhandenen Referenzen im Projektstil ein finales Referenzbild erzeugt, ohne Haken wird die Originalzeichnung direkt zur Gruppe hinzugefügt",
"手机扫码打开画布(同一局域网);画构图线稿并配文字说明,提交后结合本组已有参考图与项目风格生成最终参考图,自动加入本组;画布页取消勾选「AI 加工」则手绘原图直接加入本组": "QR-Code mit dem Handy scannen, um die Zeichenfläche zu öffnen (gleiches LAN); Layoutskizze zeichnen und Textnotiz ergänzen – nach dem Absenden wird aus Skizze, vorhandenen Referenzen der Gruppe und Projektstil ein finales Referenzbild erzeugt und automatisch hinzugefügt; „KI-Überarbeitung“ auf der Zeichenseite abwählen, um die Originalzeichnung direkt hinzuzufügen",
"✅ 手绘原图已加入本组参考图": "✅ Originalzeichnung zu den Referenzbildern dieser Gruppe hinzugefügt",
"手机扫码打开画布(同一局域网);画好提交后由 AI 按分镜草图风格重绘作为该分镜的草图;画布页取消勾选「AI 加工」则手绘原图直接作为草图": "QR-Code mit dem Handy scannen (gleiches LAN), um die Zeichenfläche zu öffnen; nach dem Absenden zeichnet die KI sie im Storyboard-Skizzenstil neu als Skizze dieser Einstellung; „KI-Überarbeitung“ auf der Zeichenseite abwählen, um die Originalzeichnung direkt zu verwenden",
"手机扫码画一张草图;默认由 AI 按分镜草图风格重绘,画布页取消勾选「AI 加工」则原图直接作为这一镜的草图": "Mit dem Handy scannen und eine Skizze zeichnen; standardmäßig zeichnet die KI sie im Storyboard-Skizzenstil neu – „KI-Überarbeitung“ auf der Zeichenseite abwählen, um das Original als Skizze dieser Einstellung zu verwenden",
"手绘稿 AI 加工": "Handzeichnung mit KI überarbeitet",
"✅ 已收到手绘稿,AI 正在按分镜草图风格重绘…": "✅ Zeichnung erhalten; die KI zeichnet sie im Storyboard-Skizzenstil neu…",
"MiniMax H3 Max Lip Sync(Fal 托管;对口型:1 张人物图 + 1 段 5–14.8 秒音频,无提示词,成片时长随音频,480P/768P/1080P/2K)": "MiniMax H3 Max Lip Sync (auf Fal gehostet; Lippensynchronisation: 1 Personenbild + 1 Audioclip von 5–14,8 s, kein Prompt, Länge folgt dem Audio, 480P/768P/1080P/2K)",
"MiniMax H3 Max Lip Sync:每段都用第 1 张参考图作人物图(画面不漂,但段与段之间会跳);画幅随图片": "MiniMax H3 Max Lip Sync: Jeder Clip nutzt Referenz #1 als Personenbild (kein Drift, aber Sprünge zwischen Clips); Seitenverhältnis folgt dem Bild",
"MiniMax H3 Max Lip Sync:首轮用第 1 张参考图作人物图,之后每轮用上一段尾帧(衔接模式选「不衔接」则每段都用第 1 张参考图);画幅随图片": "MiniMax H3 Max Lip Sync: Runde 1 nutzt Referenz #1 als Personenbild, danach das letzte Bild des vorherigen Clips (mit „Nicht verknüpfen“ immer Referenz #1); Seitenverhältnis folgt dem Bild",
"对口型模型需要至少 1 张参考图(第 1 张作为人物图)": "Das Lip-Sync-Modell benötigt mindestens 1 Referenzbild (Referenz #1 ist das Personenbild)",
"💬 台词": "💬 Sprechtext",
"人物要说的话;按句分段,逐段语音合成后驱动口型": "Was die Figur sagt; nach Sätzen aufgeteilt, jeder Abschnitt wird zu Sprache synthetisiert und steuert dann die Lippen",
"例如:大家好,欢迎来到我的直播间!今天想和大家聊一聊最近在看的一本书。": "z. B.: Hallo zusammen, willkommen in meinem Stream! Heute möchte ich über ein Buch sprechen, das ich gerade lese.",
"语音用「生成模型」页当前的 TTS 配置与默认音色合成({tts})。台词念完不会停播,会等你更新台词:在原文后面追加的部分接着念,整段改写则从头念新台词。": "Die Sprache wird mit den aktuellen TTS-Einstellungen und der Standardstimme der Seite „Generierungsmodelle“ synthetisiert ({tts}). Ist der Text zu Ende, stoppt der Stream nicht, sondern wartet auf eine Aktualisierung: Hinten angefügter Text wird anschließend gesprochen, ein umgeschriebener Text beginnt von vorn.",
"对口型:台词按句打包成每段约该秒数({lo}–{hi} 秒)的小段;每段成片时长 = 该段语音时长(不足 5 秒补静音)": "Lip Sync: Der Text wird satzweise zu Abschnitten von etwa dieser Länge gepackt ({lo}–{hi} s); jeder Clip dauert so lange wie seine Sprache (unter 5 s mit Stille aufgefüllt)",
"✏️ 更新台词": "✏️ Sprechtext aktualisieren",
"台词已更新": "Sprechtext aktualisiert",
"对口型模型需要填写台词(人物要说的话)": "Das Lip-Sync-Modell benötigt einen Sprechtext (was die Figur sagt)",
