"本地 ComfyUI + InfiniteTalk;使用本地服务地址和": "Lokales ComfyUI + InfiniteTalk; nutzt die lokale Serveradresse und das API-JSON in",
"中的 API JSON(「测试连接」会检查 MultiTalk 节点是否就绪);API 工作流使用": "(„Verbindung testen“ prüft, ob die MultiTalk-Nodes bereit sind); der API-Workflow nutzt",
"占位符": "als Platzhalter",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(InfiniteTalk API JSON,API 工作流使用": "erstellen (Comfy-Cloud-Abo erforderlich, monatliche Credits werden mit der Web-Version geteilt; der Gratis-Tarif hat keinen API-Zugang); das Workflow-Dropdown ist identisch mit lokal (InfiniteTalk-API-JSON; der API-Workflow nutzt",
"占位符);MultiTalk 等自定义节点在云端可能不可用,以「测试连接」结果为准": "als Platzhalter); Custom-Nodes wie MultiTalk sind in der Cloud ggf. nicht verfügbar — maßgeblich ist das Ergebnis von „Verbindung testen“",
"云端执行(按运行秒数扣 RH 币),不使用本地服务地址或本地 JSON;API Key 在": "(RH Coins werden pro Laufzeitsekunde abgebucht), ohne lokale Serveradresse oder lokales JSON; den API Key auf der",
"获取;请先在工作区跑通数字人工作流,再把工作流 ID 或页面链接粘贴到「添加工作流」验证;普通导出件只要执行图中各有唯一的": "erstellen; zuerst den Digitaler-Mensch-Workflow im Workspace erfolgreich durchlaufen lassen, dann die Workflow-ID oder den Seitenlink unter „Workflow hinzufügen“ einfügen und prüfen; bei einem normalen Export genügt es, wenn der Ausführungsgraph genau je einen",
