"选中剧本文字可标记「关键情节」或「关键细节」。关键点必须在分镜中体现；取消需确认。": "Markierter Drehbuchtext lässt sich als „Schlüsselhandlung“ oder „Schlüsseldetail“ kennzeichnen. Schlüsselpunkte müssen im Storyboard vorkommen; das Entfernen erfordert eine Bestätigung.",
