"分镜背景图 {ep}/{sid}({role};文件 {file};库 key {key};修订命令 python code/revise_shot_plate.py --project {proj} --ep {ep} --shot {sid} --role {r} --change \"<英文修改要求>\":以当前图为参考按意见新出一张并替换本镜该背景图,原图不动)": "Shot-Hintergrund {ep}/{sid} ({role}; Datei {file}; Bibliotheksschlüssel {key}; Überarbeitungsbefehl python code/revise_shot_plate.py --project {proj} --ep {ep} --shot {sid} --role {r} --change \"<Änderung auf Englisch>\": erzeugt aus dem aktuellen Bild gemäß Feedback ein neues und tauscht es für diesen Shot ein; das Original bleibt unverändert)",
"对这张分镜背景图提修改意见,发给修改师处理:以这张图为参考按意见新出一张替换本镜背景图,原图不动": "Feedback zu diesem Shot-Hintergrund an den Überarbeiter senden: aus diesem Bild wird gemäß Feedback ein neues erzeugt und für diesen Shot eingetauscht; das Original bleibt unverändert",
"九宫格补图": "3×3-Raster-Ergänzung",
"🔁 换分镜背景图 —": "🔁 Shot-Hintergrund tauschen —",
"从本场景的背景图库里点选一张(双击看大图),确认后替换本镜这张背景图:改写集索引 directing/<ep>/shot_plates.json 并同步本组 prompt 的参考图;随本组重出生效,非强制重出不会被自动改回": "Wählen Sie ein Bild aus der Hintergrundbibliothek dieser Szene (Doppelklick zum Vergrößern); nach Bestätigung ersetzt es den Hintergrund dieses Shots: der Index directing/<ep>/shot_plates.json wird neu geschrieben und die Prompt-Referenzen der Gruppe werden synchronisiert. Wirkt beim Neurendern der Gruppe; ein nicht erzwungenes Neurendern setzt es nicht zurück",
