// 生成模型设置·超分板块 + 成片发布页组 clip 方法标签(2026-09-23,models.html / preview_videos.html)
"图像 / 视频 / 数字人 / 超分 / 音乐 / TTS旁白 / 世界模型 生成渠道与模型": "Anbieter und Modelle: Bild / Video / Digitaler Mensch / Upscaling / Musik / TTS-Erzählung / Weltmodell",
"🔍 超分": "🔍 Upscaling",
"生效渠道=当前选中的标签页(✅),不再跟随视频渠道,保存后生效": "Aktiver Anbieter = gewählter Tab (✅), folgt nicht mehr dem Videoanbieter; gilt nach dem Speichern",
"缩放算法": "Skalierungsfilter",
"lanczos(默认,较锐利)": "lanczos (Standard, schärfer)",
"bicubic(平滑)": "bicubic (weich)",
"bilinear(最软)": "bilinear (am weichsten)",
"0–51,越小画质越高体积越大;18 ≈ 视觉无损": "0–51; kleiner = höhere Qualität und größere Datei; 18 ≈ visuell verlustfrei",
"编码预设": "Encoder-Preset",
"slow(默认)": "slow (Standard)",
"内置非 AI 插值放大:ffmpeg scale 滤镜 + libx264 重编码,音轨流拷贝,fps/时长/画幅不变。不生成新细节,只是像素变多;不花生成费,适合只需过发布规格的项目。目标尺寸由「输出设置」成片分辨率 × 画幅自动换算。": "Eingebaute Nicht-KI-Interpolation: ffmpeg-scale-Filter + libx264-Neukodierung, Audio als Stream-Kopie, fps/Dauer/Seitenverhältnis unverändert. Erzeugt keine neuen Details, nur mehr Pixel; ohne Generierungskosten, geeignet für Projekte, die nur die Veröffentlichungsspezifikation erfüllen müssen. Zielgröße aus Lieferauflösung × Seitenverhältnis der Ausgabeeinstellungen.",
"Seedance 2.5 样片(Draft)模式:选中即激活,无需另填 Key 或模型,凭证与模型沿用视频生成的火山引擎标签页。": "Seedance-2.5-Draft-Modus: mit Auswahl dieses Tabs aktiv; kein zusätzlicher Key oder Modell nötig, Zugangsdaten und Modell stammen aus dem Volcano-Engine-Tab der Videogenerierung.",
"激活条件:视频生效渠道为火山引擎(或 BytePlus,方舟同一 API)且模型为 Seedance 2.5;项目「输出设置」草稿分辨率 = 480p、成片分辨率 = 1080p(官方:样片仅 480p,出原片仅 1080p)。不满足时视频照常按普通模式生成,并在日志提示。": "Bedingungen: aktiver Videoanbieter ist Volcano Engine (oder BytePlus, gleiche Ark-API) mit einem Seedance-2.5-Modell, und die Ausgabeeinstellungen des Projekts nutzen Entwurf 480p und Lieferung 1080p (offiziell: Entwürfe nur 480p, Finals nur 1080p). Andernfalls wird normal generiert und im Protokoll vermerkt.",
"工作方式:① 生成阶段自动带 draft=true 出 480p 样片(token 用量与普通 480p 一致),Draft 任务 ID 写进组 clip 同名 meta.json 的 draft_task 段;② 超分阶段 genmedia.py upscale 按该 ID 让方舟复用同一提示词/素材/时长/画幅/seed/音频设置生成 1080p 原片(正常推理计费),画面关键要素与过审样片一致;③ Draft 任务 ID 自创建起 7 天有效,过期只能重出样片。": "Ablauf: ① Die Generierung sendet draft=true und erzeugt einen 480p-Entwurf (gleicher Tokenverbrauch wie normales 480p); die Draft-Task-ID wird in den Block draft_task der meta.json des Clips geschrieben; ② beim Upscaling lässt genmedia.py upscale Ark aus dieser ID das 1080p-Final rendern, mit denselben Prompt/Medien/Dauer/Seitenverhältnis/Seed/Audio-Einstellungen (normale Abrechnung), sodass die Kernelemente dem freigegebenen Entwurf entsprechen; ③ eine Draft-Task-ID gilt 7 Tage ab Erstellung, danach muss der Entwurf neu erzeugt werden.",
"适用条件(源 clip 必须是 MiniMax-H3 768P 直出规格):含音轨;24 fps;宽高均能被 32 整除;面积 ≤ 768×1344;107–362 帧(约 4–15 秒)。": "Voraussetzungen (Quellclip muss native MiniMax-H3-768P-Ausgabe sein): mit Tonspur; 24 fps; Breite und Höhe durch 32 teilbar; Fläche ≤ 768×1344; 107–362 Frames (ca. 4–15 s).",
"云端超分工作流": "Cloud-Upscaling-Workflow",
"超分工作流 API": "Upscaling-Workflow-API",
"创建(需 Comfy Cloud 订阅,与网页版共用月度额度,免费档无 API 权限);工作流下拉与本地一致(comfy/scale-* 模板;SeedVR2 节点 ComfyUI 官方内置,云端可用);长片 1080p 以上在云端可能显存不足,以任务结果为准": "(Comfy-Cloud-Abo nötig, teilt das Monatsguthaben mit der Web-Version; die kostenlose Stufe hat keinen API-Zugang); die Workflow-Liste entspricht der lokalen (comfy/scale-*-Vorlagen; SeedVR2-Knoten sind im offiziellen ComfyUI eingebaut und in der Cloud verfügbar); lange Clips ab 1080p können in der Cloud den Grafikspeicher sprengen, maßgeblich ist das Task-Ergebnis",
"获取;请先在工作区跑通 SeedVR2 类超分工作流,再把工作流 ID 或页面链接粘贴到「添加工作流」验证;无占位符的普通导出件系统会直绑唯一的源视频加载节点(LoadVideo 系)+ SeedVR2Preprocess 上游的缩放节点(目标边长/宽高)+ 采样器种子,也兼容 VIDEO/WIDTH/HEIGHT/SEED 占位符;这里的工作流收藏与视频生成板块各自独立;国内站与国际站账号与 Key 不互通": "; bringen Sie zuerst einen SeedVR2-artigen Upscaling-Workflow im Arbeitsbereich zum Laufen und fügen Sie dann seine Workflow-ID oder Seiten-URL bei „Workflow hinzufügen“ zur Prüfung ein; bei einem normalen Export ohne Platzhalter bindet das System den einzigen Quellvideo-Ladeknoten (LoadVideo-Familie) + den Resize-Knoten vor SeedVR2Preprocess (Zielkante / Breite+Höhe) + den Sampler-Seed; VIDEO/WIDTH/HEIGHT/SEED-Platzhalter werden ebenfalls unterstützt; die Favoriten hier sind unabhängig von der Videokarte; .cn- und .ai-Konten und -Keys sind nicht austauschbar",
"🧩 组 clip 与超分方法": "🧩 Gruppenclips und Upscaling-Methode",
"{n} 组 · assets/clips/{ep}/": "{n} Gruppen · assets/clips/{ep}/",
"未超分": "Nicht hochskaliert",
"插值放大": "Interpoliert",
"AI 超分": "KI-Upscaling",
"未知方法": "Unbekannte Methode",
