// 集尾收束(2026-09-25):视频节奏弹窗「集尾收束」行 + 分镜预览页过场汇总条集尾行
"集尾收束": "Episodenabschluss",
"切黑(突然黑屏)": "Schnitt auf Schwarz (plötzlicher Blackout)",
"切白": "Schnitt auf Weiß",
"不处理(停在末帧)": "Keine (letztes Bild stehen lassen)",
"随画面淡出": "Mit dem Bild ausblenden",
"到黑即静音": "Stille bei Schwarz",
"声音随画面淡出": "Ton blendet mit dem Bild aus",
"停留": "Halten",
"集尾": "Episodenende",
"本集覆盖": "Episoden-Override",
"按下方「集尾收束」": "siehe unten „Episodenabschluss“",
"集尾淡出时长需在 0.3–3 秒之间": "Abschluss-Ausblendung muss 0,3–3 s sein",
"集尾停留需在 0–3 秒之间": "Abschluss-Halten muss 0–3 s sein",
"切黑须停留 >0 秒(否则等于停在末帧)": "Schnitt auf Schwarz braucht Halten > 0 s (sonst bleibt nur das letzte Bild stehen)",
"正片结尾的收束:最后一组尾部淡出到黑/白后停留,或直接切黑(突然黑屏,悬念感;声音默认同刻切断);外挂声轨同刻淡出/切断,片尾包装接在停留之后。出成片时由 render_transitions 落地;某一集要不同处理可在分镜预览页过场汇总条单独设。": "Wie die Episode endet: die letzte Gruppe blendet nach Schwarz/Weiß aus und hält, oder schneidet direkt auf Schwarz (plötzlicher Blackout für Spannung; der Ton bricht standardmäßig im selben Moment ab); die externe Tonspur blendet/schneidet im selben Moment, der Abspann folgt nach dem Halten. Beim finalen Rendern von render_transitions angewendet; eine Episode kann dies in der Übergangsleiste der Storyboard-Seite überschreiben.",
"正片结尾的收束:最后一组尾部淡出/切黑后停留,外挂声轨同刻淡出或切断;片尾包装接在停留之后": "Wie die Episode endet: die letzte Gruppe blendet/schneidet auf Schwarz und hält; die externe Tonspur blendet oder schneidet im selben Moment; der Abspann folgt nach dem Halten",
"本集集尾收束(集级覆盖,项目默认在「视频节奏」设置);改后出成片时落地,已有成片须重跑转场": "Abschluss dieser Episode (Episoden-Override; Projektstandard unter „Videorhythmus“); wirkt beim finalen Rendern, ein bestehender Schnitt muss die Übergänge neu rendern",
"渲染集尾预览小片:末组尾 2s + 收束,与成片同一滤镜链": "Abschluss-Vorschau rendern: letzte 2 s der letzten Gruppe + Abschluss, gleiche Filterkette wie der finale Schnitt",
// NSFW 模式(设置→高级;index.html 弹窗 + preview_storyboard.html 组卡 🔞)
"NSFW 模式": "NSFW-Modus",
"NSFW 模式:默认关;开启后可为语言/图像/视频分别指定备用模型,标记 NSFW 的工单与分镜组自动改走备用模型,主渠道内容审核拒收时自动切换重提一次": "NSFW-Modus: standardmäßig aus; eingeschaltet lässt sich für Sprache/Bild/Video jeweils ein Ausweichmodell festlegen; als NSFW markierte Tickets und Gruppen laufen automatisch über die Ausweichmodelle, und wenn der Hauptanbieter Inhalte bei der Moderation ablehnt, wird einmal automatisch umgeschaltet und erneut eingereicht",
"🔞 NSFW 模式": "🔞 NSFW-Modus",
"启用 NSFW 模式": "NSFW-Modus aktivieren",
"默认关。开启后可分别指定三类「备用模型」;派单与出图/出片按三层路由决定何时改用备用模型:① 显式标记优先——工单带 nsfw: true(总制片按剧本拆解表事件 content_flags → 分镜组 nsfw 推导,或你在分镜预览组卡点 🔞 手动标记)首次派单即走备用模型;② 兜底——主渠道返回内容审核拒收时,genmedia 同一调用内改备用渠道重提一次(不计重跑次数)并把该组记为 NSFW,后续不再先撞主模型;语言模型被拒不做进程内切换,同一 task_id 重派时改用备用语言模型。本模式只决定用哪套模型,不放宽内容安全审核与平台分级。": "Standardmäßig aus. Eingeschaltet lässt sich für jede der drei Arten ein „Ausweichmodell“ festlegen; Beauftragung und Bild-/Videogenerierung entscheiden über drei Stufen, wann das Ausweichmodell genutzt wird: ① explizite Markierung zuerst — ein Ticket mit nsfw: true (der Producer leitet das Gruppen-nsfw aus den Ereignis-content_flags der Drehbuchaufschlüsselung ab, oder Sie markieren die Gruppe manuell mit 🔞 auf der Gruppenkarte in der Storyboard-Vorschau) läuft schon bei der ersten Beauftragung über das Ausweichmodell; ② Auffangnetz — liefert der Hauptanbieter eine Ablehnung durch die Inhaltsmoderation, reicht genmedia im selben Aufruf einmal beim Ausweichanbieter erneut ein (zählt nicht als Wiederholung) und merkt die Gruppe als NSFW vor, sodass sie künftig nicht mehr zuerst auf das Hauptmodell trifft; ein abgelehntes Sprachmodell wird nicht im laufenden Prozess gewechselt — bei erneuter Beauftragung derselben task_id wird das Ausweich-Sprachmodell verwendet. Dieser Modus entscheidet nur, welcher Modellsatz verwendet wird; er lockert weder die Inhaltssicherheitsprüfung noch die Altersfreigaben der Plattformen.",
"图像模型": "Bildmodell",
"渠道须已在「🎨 生成模型」页配好 Key(未配置的置灰);留「不设置」= 该类不切换,照常走主模型。ComfyUI 的二级选项是运行方式。备用渠道不可用时不会偷跑主模型,而是报错交你裁决。": "Der Anbieter muss auf der Seite „🎨 Generative Modelle“ bereits einen Key konfiguriert haben (nicht konfigurierte sind ausgegraut); „Nicht festgelegt“ belassen = diese Art wechselt nicht und läuft wie gewohnt über das Hauptmodell. Bei ComfyUI ist die zweite Ebene der Ausführungsmodus. Ist der Ausweichanbieter nicht verfügbar, wird nicht heimlich das Hauptmodell ausgeführt, sondern ein Fehler zur Entscheidung gemeldet.",
"审核拒收后自动切换": "Nach Moderationsablehnung automatisch umschalten",
"关闭后只按显式标记路由,主渠道审核拒收照常报错": "Ausgeschaltet wird nur nach expliziter Markierung geroutet; eine Moderationsablehnung des Hauptanbieters führt wie gewohnt zu einem Fehler",
"该运行方式未配置": "Dieser Ausführungsmodus ist nicht konfiguriert",
"生成模型页当前所选": "aktuell auf der Seite Generative Modelle gewählt",
"生成模型页所选运行方式": "Auf der Seite Generative Modelle gewählter Ausführungsmodus",
"该渠道默认模型": "Standardmodell des Anbieters",
"✓ 已开启:标记 NSFW 的工单/分镜组改走备用模型": "✓ An: als NSFW markierte Tickets/Gruppen laufen über die Ausweichmodelle",
"已关闭:全部按主模型执行": "Aus: alles läuft über die Hauptmodelle",
"不设置": "Nicht festgelegt",
"(未配 Key)": "(kein Key)",
"(未登录)": "(nicht angemeldet)",
"手动标记": "manuelle Markierung",
"分镜表按事件 content_flags 推导": "aus den Ereignis-content_flags der Einstellungsliste abgeleitet",
"本组已标记 NSFW({src}):图像/视频走备用渠道,派单带 nsfw: true;点击取消标记": "Diese Gruppe ist als NSFW markiert ({src}): Bild/Video laufen über den Ausweichanbieter, die Beauftragung trägt nsfw: true; klicken, um die Markierung zu entfernen",
"标记本组为 NSFW:图像/视频改走「设置→高级→NSFW 模式」的备用渠道,派单带 nsfw: true": "Diese Gruppe als NSFW markieren: Bild/Video laufen über den Ausweichanbieter aus „Einstellungen → Erweitert → NSFW-Modus“, die Beauftragung trägt nsfw: true",
"已标记": "markiert",
"🔞 本组文字命中敏感词 {words},但未标记 NSFW:如需改走备用模型请点「🔞」标记本组(机检 nsfw_hint 只提示不路由)": "🔞 Der Text dieser Gruppe enthält sensible Wörter {words}, ist aber nicht als NSFW markiert: Klicken Sie auf 「🔞」, um die Gruppe zu markieren, falls sie die Fallback-Modelle nutzen soll (die Prüfung nsfw_hint gibt nur Hinweise, sie routet nie)",
"❌ 投影机检未过": "❌ Projektionsprüfung fehlgeschlagen",
"❌ 白模一致性未过": "❌ Whitebox-Übereinstimmung fehlgeschlagen",
