"🗄 重出前旧版": "🗄 Vorherige Version (vor Neuerstellung)",
"归档图 {n} 张(未入索引;目视认可可「认领」为正式全景,不花钱)": "{n} archivierte Bilder (nicht indexiert; bei Sichtfreigabe per „Übernehmen“ zum offiziellen Panorama, kostenlos)",
"按别的锚点位姿出的图,不能认领": "Mit anderer Ankerpose erzeugt; nicht übernehmbar",
"不是 2:1,不能认领": "Nicht 2:1; nicht übernehmbar",
"该方案已有正式全景,先重出或挪走才能认领": "Dieses Schema hat bereits ein offizielles Panorama; erst neu erstellen oder verschieben",
"目视认可这张全景后认领为正式全景(等同 render_scene_panos.py --adopt,不花钱;之后分镜背景图链用它出图)": "Nach Sichtfreigabe dieses Panorama als offizielles übernehmen (wie render_scene_panos.py --adopt, kostenlos; die Plate-Kette rendert danach daraus)",
