"把 {anchor} 的这张归档图认领为方案 {scheme} 的正式全景?\n{file}\n\n不花钱;认领后分镜背景图链按它出图。机检数值照实记入 sidecar。": "Dieses archivierte Bild von {anchor} als offizielles Panorama für Schema {scheme} übernehmen?\n{file}\n\nKostenlos; die Plate-Kette rendert danach daraus. Prüfwerte werden unverändert im Sidecar vermerkt.",
