"弃用这张归档图:挪进该锚点的 discarded/ 目录,本页不再显示、也不能再认领(文件不删,可手工挪回)": "Dieses archivierte Bild verwerfen: Es wird in den Ordner discarded/ des Ankers verschoben, hier nicht mehr angezeigt und kann nicht mehr übernommen werden (die Datei bleibt erhalten und kann von Hand zurückgeschoben werden)",
