"天底未拉伸:底部纹理横/纵细节比 {aniso} > {limit}(像广角照片的清晰前景)": "Nadir nicht gestreckt: horizontales/vertikales Detailverhältnis des Bodenbands {aniso} > {limit} (wirkt wie der scharfe Vordergrund eines Weitwinkelfotos)",
"天顶/天底不成色带(行方差 {top}/{bot})且左右缘接不上(接缝比 {seam})": "Zenit/Nadir bilden keine Farbbänder (Zeilenvarianz {top}/{bot}) und die linke/rechte Kante schließen nicht (Nahtverhältnis {seam})",
"左右缘接不上(接缝比 {seam} > {limit}),且机位 {cams} 的视域跨过接缝,接缝会落进背景图": "Linke/rechte Kante schließen nicht (Nahtverhältnis {seam} > {limit}), und die Kameras {cams} blicken über die Naht, sodass sie in die Hintergrund-Plates fiele",
"近地前景偏实(底部/中段横向细节比 {nadir})": "Bodennaher Vordergrund zu fest (horizontales Detailverhältnis unten/Mitte {nadir})",
"近地前景偏实(底部/中段横向细节比 {nadir}),俯拍机位 {cams} 的背景图留意地面纹理尺度": "Bodennaher Vordergrund zu fest (horizontales Detailverhältnis unten/Mitte {nadir}); bei den Plates der Aufsicht-Kameras {cams} auf den Maßstab der Bodentextur achten",
"左右缘接不上(接缝比 {seam} > {limit})": "Linke/rechte Kante schließen nicht (Nahtverhältnis {seam} > {limit})",
